      "arFull": "وَاضْمُمْ یَدَكَ اِلٰی جَنَاحِكَ تَخْرُجْ بَیْضَآءَ مِنْ غَیْرِ سُوْٓءٍ اٰیَةً اُخْرٰی ۟ۙ",
