      "number": 39,
      "arFull": "اَنِ اقْذِفِیْهِ فِی التَّابُوْتِ فَاقْذِفِیْهِ فِی الْیَمِّ فَلْیُلْقِهِ الْیَمُّ بِالسَّاحِلِ یَاْخُذْهُ عَدُوٌّ لِّیْ وَعَدُوٌّ لَّهٗ ؕ وَاَلْقَیْتُ عَلَیْكَ مَحَبَّةً مِّنِّیْ ۚ۬ وَلِتُصْنَعَ عَلٰی عَیْنِیْ ۟ۘ",
      "ur": "کہ تو اسے صندوق میں بند کرکے دریا میں چھوڑ دے، پس دریا اسے کنارے ﻻ ڈالے گا اور میرا اور خود اس کا دشمن اسے لے لے گا[1] ، اور میں نے اپنی طرف کی خاص محبت ومقبولیت تجھ پر ڈال دی[2]۔ تاکہ تیری پرورش میری آنکھوں کے سامنے[3] کی جائے.",
      "en": "[Saying], 'Cast him into the chest and cast it into the river, and the river will throw it onto the bank; there will take him an enemy to Me and an enemy to him.' And I bestowed upon you love from Me[835] that you would be brought up under My eye [i.e., observation and care].",
      "footnotesUr": "[1] مراد فرعون ہے جو اللہ کا بھی دشمن اور حضرت موسیٰ (عليه السلام) کا بھی دشمن تھا۔ یعنی لکڑی کا وہ تابوت تیرتا ہواجب شاہی محل کے کنارے پہنچا تو اسے باہر نکال کر دیکھا گیا، تو اس میں ایک معصوم بچہ تھا، فرعون نے اپنی بیوی کی خواہش پر پرورش کے لئے شاہی محل میں رکھ لیا۔\n[2] یعنی فرعون کے دل میں ڈال دی یا عام لوگوں کے دلوں میں تیری محبت ڈال دی۔\n[3] چنانچہ اللہ کی قدرت کا اور اس کی حفاظت و نگہبانی کا کمال اور کرشمہ دیکھئے کہ جس بچے کی خاطر، فرعون بیشمار بچوں کو قتل کروا چکا، تاکہ وہ زندہ نہ رہے، اسی بچے کو اللہ تعالٰی اس کی گود میں پلوا رہا ہے، اور ماں اپنے بچے کو دودھ پلا رہی ہے، لیکن اس کی اجرت بھی اسی دشمن موسیٰ (عليه السلام) سے وصول کر رہی ہے۔ (فَسُبْحَانَ ذِي الْجَبَرُوتِ وَالْمَلَكُوتِ وَالْكِبْرِيَاءِ وَالْعَظَمَةِ)",
      "footnotesEn": "[835] Allāh put love of Moses into the hearts of the people.",
