      "arFull": "فَاَجْمِعُوْا كَیْدَكُمْ ثُمَّ ائْتُوْا صَفًّا ۚ وَقَدْ اَفْلَحَ الْیَوْمَ مَنِ اسْتَعْلٰی ۟",
