      "arFull": "قَالُوْا یٰمُوْسٰۤی اِمَّاۤ اَنْ تُلْقِیَ وَاِمَّاۤ اَنْ نَّكُوْنَ اَوَّلَ مَنْ اَلْقٰی ۟",
