      "arFull": "وَاَلْقِ مَا فِیْ یَمِیْنِكَ تَلْقَفْ مَا صَنَعُوْا ؕ اِنَّمَا صَنَعُوْا كَیْدُ سٰحِرٍ ؕ وَلَا یُفْلِحُ السَّاحِرُ حَیْثُ اَتٰی ۟",
