      "arFull": "فَوَسْوَسَ اِلَیْهِ الشَّیْطٰنُ قَالَ یٰۤاٰدَمُ هَلْ اَدُلُّكَ عَلٰی شَجَرَةِ الْخُلْدِ وَمُلْكٍ لَّا یَبْلٰی ۟",
      "ur": "لیکن شیطان نے اسے وسوسہ ڈاﻻ، کہنے لگا کہ میں تجھے دائمی زندگی کا درخت اور بادشاہت بتلاؤں کہ جو کبھی پرانی نہ ہو.",
