      "arFull": "وَقَالُوْا لَوْلَا یَاْتِیْنَا بِاٰیَةٍ مِّنْ رَّبِّهٖ ؕ اَوَلَمْ تَاْتِهِمْ بَیِّنَةُ مَا فِی الصُّحُفِ الْاُوْلٰی ۟",
